def get_ngram_hashes(text, n=13):
    words = text.split()
    return {hash(tuple(words[i:i+n])) for i in range(len(words) - n + 1)}

def jaccard_similarity(hashes_a, hashes_b):
    if not hashes_a or not hashes_b:
        return 0.0
    intersection = len(hashes_a & hashes_b)
    union = len(hashes_a | hashes_b)
    return intersection / union
